record.field:
if record.id:
  if 	record.tracked_item == True and record.mass_produced == True:
    size = len(record.name)
    record['original_mo'] = record.name[:size - 4]
  else:
    record['original_mo'] = record.name

if record.state == 'progress':
  rpt_id= env['sales_report_type'].search([('report_code', '=', 'Production Overview - WIP')],limit=1)
  if rpt_id:
   record['report_type_m_wip'] = rpt_id.id

if record.id:
  location = env['stock.location'].search([('id', '=', record.location_dest_id.id)], limit=1)
  if location:
    location2 = env['stock.location'].search([('location_id', '=', location.location_id.id),('finished_good_location', '=', True)], limit=1)
    if location2:
      temp = env['stock.location'].search([('temp_location', '=', True)], limit=1)
      if temp:
        record['state'] = 'draft'
        record['location_dest_id'] = temp.id
        record['finished_product_location'] = location2.id
        record['finished_products_location_updated'] = True
      else:
        raise UserError('Temp. location has not been setup.')
    else:
      raise UserError('There is no Finished Good Location is setup for the Finished Product Location in Production Order.')

if record.id:

  company_id = env.context.get('allowed_company_ids', [env.user.company_id.id])[0]
  company = env['res.company'].browse(company_id)

  serial_no = env['stock.lot'].search([('production_id', '=', record.id),('company_id', '=', company.id)])
  for lines in serial_no:
    lines.unlink()
  if record.state == 'draft':
    record['mass_produced'] = False

  record['serial_cancelled'] = True

if record.product_id:
  if record.product_id.tracking == 'serial':
    record['tracked_item'] = True
  else:
    record['tracked_item'] = False
